  'nightlife_blu-dubai': PlaceText(
    name: 'BLU Dubai',
    description: 'يُعد BLU صالة وملهى ليليًا على السطح يوفر إطلالات بانورامية على شارع الشيخ زايد. ويستضيف فنانين عالميين وليالي ذات طابع خاص وفعاليات موسيقية مفعمة بالطاقة. ويجعله موقعه المرتفع مكانًا مميزًا للسهر حتى وقت متأخر من الليل.',
    openingHours: 'يوميًا: 22:00–04:00',
  ),
  'nightlife_secret-room-dubai': PlaceText(
    name: 'Secret Room Dubai',
    description: 'يُعد Secret Room ملهى ليليًا حصريًا يركز على موسيقى الهيب هوب، ويشتهر بفكرة الدخول بالسيارات الفاخرة. ويضم تصميمه الداخلي ديكورًا بأسلوب الغرافيتي وخدمة زجاجات فاخرة. ويجذب جمهورًا عصريًا ومنسقي موسيقى عالميين. وأفادت تقارير في أكتوبر 2026 بأنه مغلق مؤقتًا، لذا تأكد قبل الزيارة.',
    openingHours: 'أُفيد بإغلاقه مؤقتًا (أكتوبر 2026)، المواعيد المعتادة: الأربعاء–السبت 23:00–04:00',
  ),
  'nightlife_the-penthouse-dubai': PlaceText(
    name: 'The Penthouse Dubai',
    description: 'يقدم The Penthouse Dubai – Rooftop Lounge & Nightclub في FIVE Palm Jumeirah تجربة ساحرة على السطح مع إطلالات بانورامية على أفق المدينة. ويشتهر بديكوره الأنيق وحياته الليلية الصاخبة ومنسقي الموسيقى من الطراز العالمي، ويمزج بين المأكولات الراقية والكوكتيلات المميزة والحفلات النابضة بالحياة في أجواء عصرية مخصصة للبالغين فقط.',
    openingHours: 'يوميًا: 17:00–04:00',
  ),
  'beaches_pools_barasti-beach': PlaceText(
    name: 'Barasti Beach',
    description: 'يُعد Barasti Beach بارًا شاطئيًا نابضًا بالحياة، ويشتهر بطابعه الاستوائي المسترخي وإطلالاته على الشاطئ وأجوائه المرحة. ويقدم موسيقى رائعة وطعامًا في أجواء غير رسمية وترفيهًا يمتد من النهار إلى الليل، وهو مكان شهير للاستلقاء تحت الشمس ومشاهدة البث الرياضي وحفلات نهاية الأسبوع الحماسية على الرمال مباشرة. وقد أُغلق المكان لإعادة التطوير في 21 يونيو 2026، ومن المتوقع أن يعيد فتح أبوابه في عام 2027.',
    openingHours: 'مغلق مؤقتًا لإعادة التطوير، يُتوقع إعادة الافتتاح في عام 2027',
  ),
  'beaches_pools_nikki-beach-dubai': PlaceText(
    name: 'Nikki Beach Dubai',
    description: 'يقدم Nikki Beach Dubai – Beach Club & Restaurant تجربة أنيقة ومعاصرة على الواجهة الشاطئية، بديكوره الأبيض المميز وموسيقاه الحية ورواده الأنيقين. ويشتهر بكبائنه الفاخرة ومأكولاته الراقية وحفلاته المرحة بجانب المسبح، ويوفر مزيجًا مثاليًا من الاسترخاء والترفيه الشاطئي النابض بالحياة.',
    openingHours: 'الثلاثاء–الأحد 11:00–19:00',
  ),
  'beaches_pools_beach-by-five-five-palm-jumeirah': PlaceText(
    name: 'Beach by FIVE | FIVE Palm Jumeirah',
    description: 'يُعد Beach by FIVE – FIVE Palm Jumeirah Dubai ناديًا شاطئيًا نابضًا بالحياة يقدم مزيجًا من الاسترخاء الفاخر وأجواء الحفلات المفعمة بالطاقة. وبشاطئه الخاص وأسرّة التشمس الأنيقة ووجباته الخفيفة الفاخرة وعروض منسقي الموسيقى الحية، يشتهر باستضافة بعض أكثر فعاليات النهار والغروب حيوية في المدينة، في أجواء ساحرة على الواجهة الشاطئية.',
    openingHours: 'يوميًا: 09:00–غروب الشمس',
  ),
  'beaches_pools_february-30': PlaceText(
    name: 'February 30',
    description: 'يُعد February 30 Dubai بارًا ومطعمًا شاطئيًا عصريًا في بالم ويست بيتش، ويشتهر بتصميمه العصري وموسيقاه المرحة وأجوائه الأنيقة على شاطئ البحر. ويقدم كوكتيلات مبتكرة وأطباقًا عالمية وأجواء حيوية تمتد من النهار إلى الليل، وهو مكان شهير لتناول الطعام على الواجهة الشاطئية والجلسات الاجتماعية المريحة.',
    openingHours: 'الاثنين–الخميس 12:00–02:00، الجمعة–السبت 10:00–03:00، الأحد 10:00–02:00',
  ),
  'beaches_pools_bla-bla-dubai': PlaceText(
    name: 'Bla Bla Dubai',
    description: 'يُعد Bla Bla Dubai، المعروف أيضًا باسم Bla Bla by McGettigan\'s، وجهة شاطئية مفعمة بالحيوية في جميرا بيتش ريزيدنس، تضم بارات وصالات ومفاهيم طعام متعددة في مكان واحد. ويشتهر بأجوائه النابضة بالحياة وإطلالاته على الشاطئ وترفيهه المتنوع، ويقدم كل شيء من الاسترخاء البسيط نهارًا إلى الحياة الليلية الصاخبة مع عروض منسقي الموسيقى وأجواء السطح.',
    openingHours: 'الأحد–الخميس: 09:00–02:00، الجمعة–السبت: 09:00–03:00',
  ),
  'beaches_pools_kite-beach': PlaceText(
    name: 'كايت بيتش',
    description: 'يُعد كايت بيتش من أكثر الشواطئ العامة شعبية في دبي، فالدخول إليه مجاني ويوفر إطلالة واضحة على برج العرب. ويشتهر بركوب الأمواج بالطائرات الورقية، كما يضم مسارًا للجري وركوب الدراجات بطول 14 كم، وملاعب كرة طائرة مجانية، وصالة رياضية في الهواء الطلق، ومزيجًا حيويًا من شاحنات الطعام والمقاهي، مما يجعله مكانًا مفضلًا للأيام النشطة ولحظات الغروب الهادئة.',
  ),
  'beaches_pools_nobu-by-the-beach': PlaceText(
    name: 'Nobu by the Beach',
    description: 'يُعد Nobu by the Beach أول نادٍ للمسبح والشاطئ من العلامة اليابانية الشهيرة، ويقع في أتلانتس ذا رويال على نخلة جميرا. ويشتهر بمسبحه اللامتناهي وأسرّته الخاصة وكبائنه، ويجمع بين أجواء مريحة بموسيقى هادئة وأطباق Nobu المميزة على مقربة من البحر. ومنطقة المسبح مخصصة للضيوف الذين تبلغ أعمارهم 21 عامًا فأكثر.',
    openingHours: 'المسبح: يوميًا 10:00–19:00، المطعم: يوميًا 12:00–22:00، البار: يوميًا 12:00–23:00',
  ),
  'beaches_pools_summersalt-beach-club': PlaceText(
    name: 'Summersalt Beach Club',
    description: 'يُعد Summersalt Beach Club وجهة أنيقة على الواجهة البحرية في جميرا النسيم، مع إطلالة مباشرة على برج العرب. ويقضي الضيوف يومهم بين شاطئه الخاص ومسبحه، بينما يضبط منسقو الموسيقى الأجواء، وتُقدَّم قائمة مستوحاة من أمريكا اللاتينية من وقت الغداء حتى وقت متأخر.',
    openingHours: 'نادي الشاطئ: يوميًا 09:00–غروب الشمس، المطعم: يوميًا 12:30–00:00',
  ),
  'culture_museums_al-fahidi-historical-neighbourhood': PlaceText(
    name: 'حي الفهيدي التاريخي',
    description: 'حي الفهيدي التاريخي، الذي يُطلق عليه غالبًا اسم البستكية، من أكثر أحياء دبي تميزًا بأجوائه وأهميته الثقافية. ويتميز بأزقته الضيقة وعمارته التقليدية ذات أبراج الهواء وبيوته المرممة ذات الأفنية، ويقدم نظرة نادرة على الحياة في دبي قبل ظهور أفقها الحديث. ويزخر الحي بالمتاحف والمعارض الفنية والمقاهي والمراكز الثقافية مثل مركز الشيخ محمد للتواصل الحضاري، حيث يمكن للزوار التعرف على التقاليد الإماراتية عن كثب. وبأجوائه الهادئة وممراته الرملية ومبانيه الغنية بالتراث، يقدم الفهيدي رحلة عميقة المعنى إلى ماضي المدينة، ويبقى وجهة لا بد من زيارتها لعشاق التاريخ والثقافة والفن.',
    openingHours: 'يوميًا: 07:00–20:00',
  ),
  'culture_museums_etihad-museum': PlaceText(
    name: 'متحف الاتحاد',
    description: 'متحف الاتحاد معلم ثقافي حديث في دبي صُمم بإتقان، ويروي قصة تأسيس دولة الإمارات العربية المتحدة وهويتها الوطنية. ويقع في الموقع التاريخي الذي شهد توقيع اتفاقية الاتحاد عام 1971، ويضم معارض تفاعلية وصورًا أرشيفية وأفلامًا وقطعًا أثرية تعيد إلى الحياة مسيرة توحيد البلاد. وترمز عمارته المعاصرة الأنيقة، المصممة على شكل مخطوطة، إلى توقيع الدستور. وبقاعاته الغامرة ومعروضاته المنتقاة بعناية، يقدم متحف الاتحاد نظرة ثرية وشيقة على التاريخ السياسي لدولة الإمارات وتراثها وقيادتها صاحبة الرؤية.',
    openingHours: 'يوميًا: 10:00–20:00',
  ),
  'culture_museums_dubai-opera': PlaceText(
    name: 'دبي أوبرا',
    description: 'دبي أوبرا وجهة عالمية المستوى لفنون الأداء تقع في وسط مدينة دبي، وتشتهر بعمارتها اللافتة المستوحاة من مراكب الداو وبرامجها الثقافية الحيوية. ويستضيف المكان باقة متنوعة من العروض تشمل الأوبرا والباليه والحفلات الموسيقية والمسرح والكوميديا والعروض العائلية. وفي الداخل، يمكن للقاعة المرنة أن تتحول من مسرح تقليدي إلى قاعة حفلات موسيقية أو مساحة فعاليات بأرضية مستوية، مع صوتيات استثنائية وتجربة مشاهدة حميمة. وبفضل موقعها الخلاب بالقرب من برج خليفة ونافورة دبي، تُعد دبي أوبرا مركزًا ثقافيًا نابضًا بالحياة يجلب الفنون العالمية والترفيه إلى قلب المدينة.',
  ),
  'culture_museums_museum-of-the-future': PlaceText(
    name: 'متحف المستقبل',
    description: 'متحف المستقبل من أبرز معالم دبي، ويشتهر بتصميمه المستقبلي الحلقي الشكل المكسو بخط عربي انسيابي. وهو أكثر من مجرد متحف، إذ يقدم استكشافًا غامرًا لآفاق المستقبل في التكنولوجيا والاستدامة والفضاء والابتكار البشري. وفي الداخل، يخوض الزوار تجربة معارض تفاعلية تمزج بين العلم والخيال وأحدث التصاميم، وتمنحهم لمحة عما قد يبدو عليه العالم بعد عقود من الآن. ويقف متحف المستقبل رمزًا للتقدم والإبداع، ملهمًا زواره للتفكير بجرأة في الغد. والمتحف مغلق مؤقتًا ريثما يجري إعداد الجيل التالي من معارضه، ومن المتوقع أن يعيد فتح أبوابه في الربع الأول من عام 2027.',
    openingHours: 'مغلق مؤقتًا، يُتوقع إعادة الافتتاح في الربع الأول من عام 2027',
  ),
  'culture_museums_jumeirah-mosque': PlaceText(
    name: 'مسجد جميرا',
    description: 'يُعد مسجد جميرا من أحب المعالم في دبي، وهو من المساجد القليلة في المدينة المفتوحة لزيارة غير المسلمين. افتُتح عام 1979 وبُني بمزيج من الطرز الإسلامية التاريخية، منها الفاطمي والمملوكي، ويشتهر بقبته الأنيقة ومئذنتيه التوأمين. وتشرح الزيارات المرشدة التي ينظمها مركز الشيخ محمد بن راشد آل مكتوم للتواصل الحضاري التقاليد الإسلامية والثقافة الإماراتية، وتشمل ضيافة إماراتية خفيفة. ولا حاجة إلى حجز مسبق، ويُطلب ارتداء ملابس محتشمة، وتتوفر الملابس التقليدية في الموقع.',
    openingHours: 'الزيارات المرشدة: السبت–الخميس الساعة 10:00 و14:00',
  ),
  'shopping_dubai-mall': PlaceText(
    name: 'دبي مول',
    description: 'دبي مول من أكبر وجهات التسوق والترفيه في العالم، ويضم أكثر من 1,200 متجر. كما يحتضن معالم جذب كبرى مثل دبي أكواريوم وPLAY DXB وحلبة تزلج على الجليد بحجم أولمبي. ويقع بجوار برج خليفة، ويستقطب ملايين الزوار كل عام.',
    openingHours: 'الاثنين–الخميس 10:00–23:00، الجمعة–الأحد 10:00–00:00',
  ),
  'shopping_mall-of-the-emirates': PlaceText(
    name: 'مول الإمارات',
    description: 'يشتهر مول الإمارات بسكي دبي، أول منتجع تزلج داخلي في الشرق الأوسط. ويوفر تسوقًا فاخرًا وتجارب طعام راقية وخيارات ترفيه متنوعة. ويمزج المول بين الاستجمام والتسوق في أجواء فخمة.',
    openingHours: 'الاثنين–الخميس: 10:00–23:00، الجمعة–الأحد: 10:00–00:00',
  ),
  'shopping_city-walk': PlaceText(
    name: 'سيتي ووك',
    description: 'سيتي ووك وجهة حضرية في الهواء الطلق لأسلوب الحياة العصري، تضم متاجر بوتيك ومقاهي وفنون الشارع وأماكن للترفيه. وتمزج بين الجادات ذات الطراز الأوروبي وتصاميم دبي الحديثة. والمنطقة مقصد شهير لنزهات المساء والخروج مع العائلة.',
    openingHours: 'الاثنين–الجمعة: 10:00–23:00، السبت–الأحد: 10:00–00:00',
  ),
  'shopping_souk-madinat-jumeirah': PlaceText(
    name: 'سوق مدينة جميرا',
    description: 'سوق مدينة جميرا إعادة تصور عصرية للسوق العربي التقليدي. ويضم متاجر بوتيك ومطاعم على الواجهة المائية وقنوات خلابة تجوبها قوارب العبرة. ويوفر المكان إطلالات ساحرة على برج العرب.',
    openingHours: 'يوميًا: 10:00–23:00',
  ),
  'shopping_dubai-festival-city-mall': PlaceText(
    name: 'دبي فستيفال سيتي مول',
    description: 'دبي فستيفال سيتي مول وجهة تسوق على الواجهة المائية، ويشتهر بعرض IMAGINE بالليزر والنوافير والنار. ويوفر تشكيلة واسعة من العلامات التجارية ومعالم الجذب العائلية. ويضفي موقعه على امتداد الخور قيمة جمالية على التجربة.',
    openingHours: 'الاثنين–الخميس 10:00–22:00، الجمعة–الأحد 10:00–00:00',
  ),
  'shopping_dubai-gold-souk': PlaceText(
    name: 'سوق الذهب في دبي',
    description: 'سوق الذهب في دبي سوق تقليدي مسقوف في ديرة، يضم أكثر من 300 محل للمجوهرات ويُعرف بقوس مدخله الخشبي. ويمكن للزوار تصفح الذهب والأحجار الكريمة والمعادن النفيسة، والمساومة جزء من التجربة. ويجعله قربه من سوق التوابل ومعبر العبرة عبر خور دبي محطة سهلة لاستكشاف دبي القديمة.',
    openingHours: 'تختلف المواعيد حسب المحل، عادةً 10:00–22:00، تفتح محلات كثيرة في وقت لاحق يوم الجمعة',
  ),
  'desert_adventure_skydive-dubai': PlaceText(
    name: 'سكاي دايف دبي',
    description: 'يقدم سكاي دايف دبي قفزات مزدوجة بالمظلات تتيح لك السقوط الحر بسرعة تتجاوز 200 كم/س من ارتفاع يصل إلى 13,000 قدم، وأنت مثبت بإحكام إلى مدرب متمرس. ويمكنك القفز فوق نخلة جميرا ومعالم المدينة الشهيرة من Palm Dropzone في مرسى دبي، أو فوق كثبان الصحراء الرملية من Desert Campus في مرغم. وتتاح القفزات المزدوجة لمن تتراوح أعمارهم بين 18 و75 عامًا، مع حدود للوزن ومؤشر كتلة الجسم، لذا تحقق من الشروط قبل الحجز.',
    openingHours: 'Palm Dropzone: الخميس–الاثنين 07:00–11:00، Desert Campus: الأربعاء–الأحد 07:00–14:00',
  ),
  'desert_adventure_hero-balloon-flights-dubai': PlaceText(
    name: 'Hero Balloon Flights Dubai',
    description: 'تقدم Hero Balloon Flights Dubai تجربة هادئة وساحرة بمنطاد الهواء الساخن فوق محمية دبي الصحراوية عند شروق الشمس. ومع ارتفاعك برفق، تستمتع بإطلالات بانورامية على الكثبان الرملية المتموجة والحياة البرية الطليقة والوهج الذهبي الناعم لسماء الصباح الباكر. وبقيادة طيارين خبراء، تأتي الرحلة سلسة وآمنة ومتاحة للضيوف من سن 7 سنوات فما فوق، مما يجعلها مغامرة لا تُنسى للأزواج والعائلات والمصورين على حد سواء. وبما تجمعه من مناظر تخطف الأنفاس ولحظات هادئة في الجو، تقدم Hero Balloon Flights إحدى أكثر التجارب الصحراوية رسوخًا في الذاكرة في دبي.',
    openingHours: 'رحلات يومية عند شروق الشمس، الموسم: 1 أكتوبر–31 مايو',
  ),
  'desert_adventure_ski-dubai': PlaceText(
    name: 'سكي دبي',
    description: 'سكي دبي عالم شتوي داخلي فريد يقع في مول الإمارات، ويقدم تجربة متكاملة مع الثلج والتزلج في قلب الصحراء. ويضم هذا المعلم ثلجًا حقيقيًا ومنحدرات تزلج لجميع المستويات ومتنزهًا ثلجيًا فيه منزلقات ومناطق للتسلق، بل وفرصة للقاء طيور البطريق اللطيفة. ويمكن للزوار الاستمتاع بالتزلج أو التزلج على اللوح أو ركوب الزلاجات أو مجرد اللعب في الثلج، مهما كان الطقس في الخارج. وبأجوائه الألبية الغامرة وأنشطته الممتعة لجميع الأعمار، يقدم سكي دبي ملاذًا منعشًا وإحدى أشهر مغامرات المدينة المناسبة للعائلات.',
